	db 0x32		; mask 0x401
	times 14 db 0x00
	db 0x32		; mask 0x410
	db 0x33		; mask 0x411
	times 46 db 0x00
	db 0x32		; mask 0x440
	db 0x31		; mask 0x441
	times 14 db 0x00
	db 0x32		; mask 0x450
	db 0x32		; mask 0x451
bite_tbl_end:

